from taf.nms.nom.schemas.base import SchemaObject, SchemaObjects, SchemaField


class OperationExecutionResponse(SchemaObject):
    operation_id = SchemaField(name="operation_id")
    operation_name = SchemaField(name="operation_name")
    status = SchemaField(name="status")
    operation_attributes = SchemaField(name="operation_attributes")
    operation_scope_id = SchemaField(name="operation_scope_id")
    user_name = SchemaField(name="user_name")
    user_provided_operation_name = SchemaField(name="user_provided_operation_name")
    user_provided_description = SchemaField(name="user_provided_description")
    parent_operation_id = SchemaField(name="parent_operation_id")
    preceding_operation_ids = SchemaField(name="preceding_operation_ids")
    has_descendants = SchemaField(name="has_descendants")
    definition_timestamp = SchemaField(name="definition_timestamp")
    status_timestamp = SchemaField(name="status_timestamp")

    def __init__(self, operation_id, operation_name, status, operation_attributes,
                 operation_scope_id, user_name, user_provided_operation_name,
                 user_provided_description, parent_operation_id, preceding_operation_ids,
                 has_descendants, definition_timestamp, status_timestamp):
        self.operation_id = operation_id
        self.operation_name = operation_name
        self.status = status
        self.operation_attributes = operation_attributes
        self.operation_scope_id = operation_scope_id
        self.user_name = user_name
        self.user_provided_operation_name = user_provided_operation_name
        self.user_provided_description = user_provided_description
        self.parent_operation_id = parent_operation_id
        self.preceding_operation_ids = preceding_operation_ids
        self.has_descendants = has_descendants
        self.definition_timestamp = definition_timestamp
        self.status_timestamp = status_timestamp

        super(OperationExecutionResponse, self).__init__()


class OperationExecutionResponses(SchemaObjects):
    schema = OperationExecutionResponse


